    xLarm := TRUE;
END_IF;

xDriftsklar := EMG_OK AND AIR_OK AND SYS_AUTO AND NOT xKravOmstart AND NOT xLarm;

SYS_ALARM := xLarm;

IF NOT xDriftsklar THEN
    ST310_RB_START := FALSE;
    ST320_RB_START := FALSE;
ELSE
    CASE steg OF
        0: (* vantar pa konsol i gripdon och ledig zon *)
            IF ST310_PRT_PRS AND ST310_ZON_FREE THEN
                ST310_RB_START := TRUE;
                steg := 1;
            END_IF;

        1: (* avlamnaren pa vag mot overlamningslaget *)
            IF ST310_RB_DONE THEN
                ST310_RB_START := FALSE;
                ST310_HSK_REQ := TRUE;
                steg := 2;
            END_IF;

        2: (* vantar pa mottagarens kvittens, kvittensvakten loper i bakgrunden *)
            IF ST310_HSK_ACK THEN
                steg := 3;
            END_IF;

        3: (* mottagaren far ga in i zonen, aldrig samtidigt med ST310 *)
            IF ST310_ZON_FREE THEN
                ST320_RB_START := TRUE;
            END_IF;
            IF ST320_RB_DONE THEN
                ST320_RB_START := FALSE;
                ST320_GRP_CLOSE := TRUE;
                steg := 4;
            END_IF;

        4: (* vantar pa att mottagarens grip haller *)
            IF ST320_GRP_CLOSED THEN
                ST310_GRP_OPEN := TRUE;
                steg := 5;
            END_IF;

        5: (* vantar pa att avlamnaren slappt och anmalt klart *)
            IF ST310_GRP_OPENED AND ST310_HSK_DONE THEN
                ST310_HSK_REQ := FALSE;
                ST310_HSK_RST := TRUE;
                steg := 6;
            END_IF;

        6: (* vantar pa att mottagaren slappt sin kvittens *)
            IF NOT ST310_HSK_ACK THEN
                ST310_HSK_RST := FALSE;
                ST310_GRP_OPEN := FALSE;
                ST320_GRP_CLOSE := FALSE;
                steg := 0;
            END_IF;
    END_CASE;
END_IF;

